<script setup>
import {computed} from 'vue';import {Head,Link,useForm} from '@inertiajs/vue3';import StudyDock from '../Components/StudyDock.vue';import Feedback from '../Components/Feedback.vue';import Errors from '../Components/Errors.vue';import {art} from '../art';
const props=defineProps({quiz:Object}),form=useForm({answers:props.quiz.answers||{}}),done=computed(()=>Object.keys(form.answers).length===props.quiz.items.length);
const confident=computed(()=>props.quiz.items.filter(i=>i.confidence===5));
const confidentCorrect=computed(()=>confident.value.filter(i=>props.quiz.answers?.[i.question.id]===i.question.key).length);
</script>
<template><Head title="Memory Maki · Recall check"/><div class="page-title"><div><h1>Recall check</h1><p>{{Object.keys(form.answers).length}}/{{quiz.items.length}} answered</p></div><img class="portrait" :src="art.memo" alt="Memo Maki"></div>
<section v-if="quiz.finished" class="panel"><h2>{{quiz.score}} / {{quiz.items.length}} correct</h2><p v-if="confident.length">Of {{confident.length}} sampled cards you rated 5, you recalled {{confidentCorrect}} correctly.</p><p v-else>No cards rated 5 were included in this small sample.</p><p>A short recall check is a snapshot of this deck, separate from your familiarity ratings. It does not predict exam readiness.</p><Link class="button primary" :href="'/flashcards/decks/'+quiz.deck_id">Return to your deck</Link></section>
<form @submit.prevent="form.post('/memory-checks/'+quiz.id)"><Errors :errors="form.errors"/><article v-for="(item,i) in quiz.items" :key="item.question.id" class="panel"><p class="eyebrow">Question {{i+1}} · {{item.question.subject}}</p><h2 class="pre question-stem">{{item.question.stem}}</h2><div class="options"><button v-for="(o,n) in item.question.options" :key="n" type="button" :disabled="quiz.finished||form.processing" :class="{selected:form.answers[item.question.id]===String.fromCharCode(65+n),correct:quiz.finished&&item.question.key===String.fromCharCode(65+n)}" @click="form.answers[item.question.id]=String.fromCharCode(65+n)"><strong>{{String.fromCharCode(65+n)}}.</strong> {{o}}</button></div><template v-if="quiz.finished"><p>Familiarity before this check: {{item.confidence||'Unrated'}} / 5</p><Feedback :question="item.question"/></template></article><StudyDock v-if="!quiz.finished"><button class="primary full" :disabled="!done||form.processing">{{form.processing?'Saving…':'Submit recall check'}}</button></StudyDock> <Link :href="'/flashcards/decks/'+quiz.deck_id">Back to deck</Link></form></template>
